// Generated by allium:propagate from spec/recipe-import.allium (entity DraftRequest: the drafts a member asked for,
// kept to count against the hourly allowance). Do not edit by hand: change the spec and propagate.
import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { memberId } from "@weekly-planner/domain";
import { afterEach, describe, expect, it } from "vitest";
import { openDatabase, type Database } from "../../src/infrastructure/sqlite/database.js";
import { SqliteDraftRequestLog } from "../../src/infrastructure/sqlite/sqlite-draft-request-log.js";

let db: Database | undefined;
afterEach(() => {
  db?.close();
  db = undefined;
});

describe("SqliteDraftRequestLog", () => {
  it("lists only the drafts asked for at or after the given time, oldest first", async () => {
    db = openDatabase(":memory:");
    const log = new SqliteDraftRequestLog(db);
    await log.add({ requestedBy: memberId("2"), requestedAt: 200 });
    await log.add({ requestedBy: memberId("3"), requestedAt: 100 });
    await log.add({ requestedBy: memberId("2"), requestedAt: 300 });
    expect(await log.listSince(150)).toEqual([
      { requestedBy: memberId("2"), requestedAt: 200 },
      { requestedBy: memberId("2"), requestedAt: 300 },
    ]);
    expect(await log.listSince(100)).toHaveLength(3);
    expect(await log.listSince(301)).toEqual([]);
  });

  it("keeps the drafts across a restart, so the allowance is not reset by one", async () => {
    const path = join(mkdtempSync(join(tmpdir(), "drafts-")), "planner.db");
    db = openDatabase(path);
    await new SqliteDraftRequestLog(db).add({ requestedBy: memberId("2"), requestedAt: 1_000 });
    db.close();
    db = openDatabase(path);
    expect(await new SqliteDraftRequestLog(db).listSince(0)).toEqual([
      { requestedBy: memberId("2"), requestedAt: 1_000 },
    ]);
  });
});
